/* repères de la tête, comme dans drawFig */
const hoHead = (J, F) => { const HS = F.look && F.look.child ? 1.4 : 1.12; return (x, y) => [J.head[0] + (J.hf[0] * x - J.hu[0] * y) * HS, J.head[1] + (J.hf[1] * x - J.hu[1] * y) * HS]; };
/* lyre (kinnor) : suspendue à une branche depuis (x, y), ou tenue */
const hoLyreDraw = (P, x, y, s, a = 0, held = 0) => {
  const R = (dx, dy) => [x + (dx * Math.cos(a) - dy * Math.sin(a)) * s, y + (dx * Math.sin(a) + dy * Math.cos(a)) * s];
  if (!held) P.line([R(0, 0), R(0, 9)], 0.7);
  P.shape([R(-9, 30), R(9, 30), R(10, 39), R(-10, 39)], 'r5y5k2', 0.7);
  P.line([R(-8, 30), R(-11, 10)], 2.2, { taper: 0 }); P.line([R(8, 30), R(12, 12)], 2.2, { taper: 0 }); P.line([R(-13, 9), R(14, 12)], 2.4, { taper: 0 });
  for (let i = -2; i <= 2; i++) P.line([R(i * 3, 11 + i * 0.4), R(i * 2.6, 30)], 0.45, { lvl: 8 });
};
Object.assign(PROPS2, {
  hoTablet(P, A, J, M, h, t, lw, F, u, n, add) { const q = M(add(A.t, u, 0.015)), s = h / 140; P.shape([[q[0] - 8 * s, q[1] - 6 * s], [q[0] + 8 * s, q[1] - 7 * s], [q[0] + 8 * s, q[1] + 6 * s], [q[0] - 8 * s, q[1] + 7 * s]], 'y4r3k1', lw * 0.6); for (let i = 0; i < 3; i++) P.line([[q[0] - 6 * s, q[1] - 3.5 * s + i * 3.5 * s], [q[0] + 6 * s, q[1] - 4 * s + i * 3.5 * s]], lw * 0.35); },
  hoStylus(P, A, J, M, h, t, lw, F, u, n, add) { P.line([M(A.w), M(add(A.t, u, 0.07))], lw * 1.3, { taper: 0.3 }); },
  hoChisel(P, A, J, M, h, t, lw, F, u, n, add) { P.line([M(A.t), M(add(A.t, u, 0.11))], lw * 2, { ink: 3, lvl: 8, taper: 0 }); },
  hoLyre(P, A, J, M, h) { const q = M(A.t), s = h / 140; hoLyreDraw(P, q[0], q[1] - 32 * s, s, 0, 1); },
  hoTimbrel(P, A, J, M, h, t, lw) { const q = M(A.t); P.shape(P.disc(q[0], q[1] - h * 0.03, h * 0.05, 14), 'r4y5k2', lw * 0.7); P.shape(P.disc(q[0], q[1] - h * 0.03, h * 0.036, 12), 'y1', lw * 0.4); },
  hoHoe(P, A, J, M, h, t, lw, F, u, n, add) { const a = add(A.w, u, -0.12), b = add(A.w, u, 0.36); P.line([M(a), M(b)], lw * 1.7, { taper: 0 }); P.shape([M(b), M(add(b, n, 0.07)), M(add(add(b, n, 0.07), u, 0.035)), M(add(b, u, 0.02))], 'k5b2', lw * 0.6); },
  /* casque conique des armées de Mésopotamie */
  hoCone(P, A, J, M, h, t, lw, F) { const H = hoHead(J, F); P.shape([H(0.066, -0.02), H(0.052, -0.08), H(0.006, -0.17), H(-0.05, -0.086), H(-0.07, -0.03), H(-0.072, 0.034), H(-0.04, 0.034), H(-0.03, -0.028)].map(M), (F.look && F.look.hc) || 'y5r3k3', lw); P.line([H(0.066, -0.022), H(-0.03, -0.03)].map(M), lw * 1.1); }
});
