/* lointains : tout ce qui est dessiné dans fn reste dans l'ovale du ciel */
const hoBack = (P, fn, o = {}) => {
  const cy = o.cy || 420, ry = o.ry || 330;
  P.ctx.save(); const cl = new Path2D(); cl.ellipse(500, cy, 480, ry, 0, 0, TAU); P.ctx.clip(cl);
  if (o.sky) P.fill([[0, 0], [1000, 0], [1000, 760], [0, 760]], o.sky, {});
  fn(); P.ctx.restore();
  const rim = []; for (let i = 0; i <= 60; i++) { const a = Math.PI * (0.86 + 1.28 * i / 60); rim.push([500 + Math.cos(a) * 480, cy + Math.sin(a) * ry]); }
  P.line(rim, 1, { lvl: 8 });
};
const hoBand = (P, y0, amp, f, tn, ph, lw = 0.8) => { const pts = [[0, 760]]; for (let x = 0; x <= 1000; x += 20) pts.push([x, y0 - Math.abs(Math.sin(x * f + ph)) * amp - Math.sin(x * f * 2.3 + ph) * amp * 0.3]); pts.push([1000, 760]); P.fill(pts, tn, {}); P.line(pts.slice(1, -1), lw, { lvl: 7 }); };
/* hameau vu de loin, posé sur une crête */
const hoHamlet = (P, x, y, n, tn = 'y3r2k1', s = 1) => { for (let i = 0; i < n; i++) { const w = (10 + (i * 7) % 6) * s, h = (8 + (i * 5) % 7) * s, x0 = x + i * 12 * s, y0 = y - ((i * 3) % 4) * 2 * s; P.shape([[x0, y0], [x0 + w, y0], [x0 + w, y0 - h], [x0, y0 - h]], i % 2 ? tn : tadd(tn, 'k1'), 0.6); P.fill([[x0 + w * 0.35, y0], [x0 + w * 0.6, y0], [x0 + w * 0.6, y0 - h * 0.5], [x0 + w * 0.35, y0 - h * 0.5]], 'k6r2', { noKnock: true }); } };
/* rempart crénelé : le long de x (face avant gauche) ou le long de y (face avant droite) */
const hoWallX = (P, x, y, len, h, tn, o = {}) => {
  const z = o.z || 0, th = o.th || 22; P.box(x, y, z, len, th, h, tn);
  for (let q = 11; q < h; q += 11) P.line([P.I(x, y + th, z + q), P.I(x + len, y + th, z + q)], 0.4);
  const n = Math.max(2, Math.floor(len / 22)), st = (len - 8) / n; for (let i = 0; i < n; i++) P.box(x + 4 + i * st, y, z + h, st * 0.55, th, 9, tn, 0.7);
};
const hoWallY = (P, x, y, len, h, tn, o = {}) => {
  const z = o.z || 0, th = o.th || 22; P.box(x, y, z, th, len, h, tn);
  for (let q = 11; q < h; q += 11) P.line([P.I(x + th, y, z + q), P.I(x + th, y + len, z + q)], 0.4);
  const n = Math.max(2, Math.floor(len / 22)), st = (len - 8) / n; for (let i = 0; i < n; i++) P.box(x, y + 4 + i * st, z + h, th, st * 0.55, 9, tn, 0.7);
};
const hoTower = (P, x, y, s, h, tn, o = {}) => {
  const z = o.z || 0; P.box(x, y, z, s, s, h, tn); P.box(x - 3, y - 3, z + h, s + 6, s + 6, 6, tadd(tn, 'k1'), 0.8);
  for (const [a, b] of [[-3, -3], [s - 7, -3], [-3, s - 7], [s - 7, s - 7]]) P.box(x + a, y + b, z + h + 6, 10, 10, 9, tn, 0.7);
  P.fill([P.I(x + s * 0.42, y + s + 0.4, z + h * 0.58), P.I(x + s * 0.58, y + s + 0.4, z + h * 0.58), P.I(x + s * 0.58, y + s + 0.4, z + h * 0.8), P.I(x + s * 0.42, y + s + 0.4, z + h * 0.8)], 'k6r2', { noKnock: true });
  P.fill([P.I(x + s + 0.4, y + s * 0.42, z + h * 0.58), P.I(x + s + 0.4, y + s * 0.58, z + h * 0.58), P.I(x + s + 0.4, y + s * 0.58, z + h * 0.8), P.I(x + s + 0.4, y + s * 0.42, z + h * 0.8)], 'k6r2', { noKnock: true });
};
/* maison à toit plat : porte sur la face avant gauche, fenêtre sur la face avant droite */
const hoHouse = (P, x, y, w, d, h, tn, o = {}) => {
  const z = o.z || 0, dh = Math.min(24, h * 0.6); P.box(x, y, z, w, d, h, tn, 0.9); P.box(x - 1, y - 1, z + h, w + 2, d + 2, 3, tadd(tn, 'k1'), 0.5);
  if (o.door !== 0) P.fill([P.I(x + w * 0.3, y + d + 0.4, z), P.I(x + w * 0.56, y + d + 0.4, z), P.I(x + w * 0.56, y + d + 0.4, z + dh), P.I(x + w * 0.3, y + d + 0.4, z + dh)], 'k6r2', { noKnock: true });
  P.fill([P.I(x + w + 0.4, y + d * 0.38, z + h * 0.52), P.I(x + w + 0.4, y + d * 0.6, z + h * 0.52), P.I(x + w + 0.4, y + d * 0.6, z + h * 0.8), P.I(x + w + 0.4, y + d * 0.38, z + h * 0.8)], 'k6r2', { noKnock: true });
};
const hoTown = (P, list, tn, z = 0) => { for (const [x, y, w, d, h, t2] of list.slice().sort((a, b) => a[0] + a[1] - b[0] - b[1])) hoHouse(P, x, y, w, d, h, t2 || tn, { z }); };
const hoOlive = (P, x, y, h = 90, z = 0) => Lib.tree(P, x, y, z, { h, r: h * 0.34, can: 'y3b4k2', trunk: 'r3y4k5', blobs: 6 });
/* chemin de terre battue : suite de points [x, y, z] */
const hoRoad = (P, pts, w = 22, tn = 'y3r1') => {
  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i], b = pts[i + 1], dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1, nx = -dy / l * w, ny = dx / l * w, za = (a[2] || 0) + 0.5, zb = (b[2] || 0) + 0.5;
    P.fill([P.I(a[0] + nx, a[1] + ny, za), P.I(b[0] + nx, b[1] + ny, zb), P.I(b[0] - nx, b[1] - ny, zb), P.I(a[0] - nx, a[1] - ny, za)], tn, {});
    if (i < pts.length - 2) P.fill(P.ell(b[0], b[1], zb, w, w, 14), tn, {});
  }
};
const hoStatic = (P, lk, o) => renderChar(P, prepChar(ch(lk, o)), o.tt || 1.3);
