/* dalle dressée à sommet cintré, face vers l'avant gauche ; renvoie un point de la face (u, v) */
const hoStele = (P, x, y, z, w, h, tn, o = {}) => {
  const th = o.th || 14, r = w / 2, k = 0.7, pts = [P.I(x, y + th, z)];
  for (let i = 0; i <= 12; i++) { const a = Math.PI - Math.PI * i / 12; pts.push(P.I(x + r + Math.cos(a) * r, y + th, z + h - r * k + Math.sin(a) * r * k)); }
  pts.push(P.I(x + w, y + th, z));
  P.shape([P.I(x + w, y, z), P.I(x + w, y + th, z), P.I(x + w, y + th, z + h - r * k), P.I(x + w, y, z + h - r * k)], tadd(tn, 'k2b1'), 1);
  P.shape(pts, tn, 1.2);
  return (u, v) => P.I(x + u * w, y + th + 0.4, z + v * h);
};
const hoCairn = (P, x, y, s = 1, tn = 'y3r2k3') => { const b = P.I(x, y, 0); for (const [dx, dy, r] of [[-7, 0, 8], [7, -1, 7], [0, -9, 7], [0, -17, 5]]) P.shape(Lib.bumpy(P, b[0] + dx * s, b[1] + (dy - 4) * s, r * s, r * s * 0.7, 5), tn, 0.7); };
